"use client";
const arabicFont = ''
import React, { useState, useCallback, useEffect, useRef } from 'react';
import axios from 'axios';
import { useRouter } from 'next/navigation';
import { FaArrowLeft, FaSpinner, FaSearch, FaFilePdf, FaFileExcel, FaUser, FaEye } from 'react-icons/fa';
import { usePermission } from '../../../context/PermissionContext';
import NotAuth from "../components/NotAuth";
import { motion, AnimatePresence } from 'framer-motion';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';
import QRCode from 'qrcode';
import CustomAwesomeButton from '../components/CustomAwesomeButton';

const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null;
const apiUrl = typeof window !== 'undefined' ? window.localStorage.getItem('apiUrl') : null;

const CustomerSearch = ({ onCustomerSelect }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);

  const handleSearch = useCallback(async () => {
    if (!searchQuery) {
      setSearchResults([]);
      return;
    }
    setIsLoading(true);
    try {
      const response = await axios.get(`${apiUrl}CustomerUsersList/search-customers-reports?query=${searchQuery}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSearchResults(response.data);
      setIsDropdownOpen(true);
    } catch (error) {
      toast.error('Error searching for customers');
    } finally {
      setIsLoading(false);
    }
  }, [searchQuery]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  useEffect(() => {
    const delayDebounceFn = setTimeout(() => {
      handleSearch();
    }, 300);

    return () => clearTimeout(delayDebounceFn);
  }, [searchQuery, handleSearch]);

  return (
    <div className="mb-8 relative" ref={dropdownRef}>
      <div className="flex items-center mb-2">
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search by name or phone"
          className="flex-grow p-3 border text-black border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all duration-300"
        />
        <div className="absolute right-3 top-3 text-gray-400">
          {isLoading ? <FaSpinner className="animate-spin" /> : <FaSearch />}
        </div>
      </div>
      <AnimatePresence>
        {isDropdownOpen && searchResults.length > 0 && (
          <motion.ul
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="absolute z-10 w-full mt-1 border border-gray-200 rounded-md shadow-lg max-h-60 overflow-y-auto bg-white"
          >
            {searchResults.map((customer) => (
              <motion.li
                key={customer._id}
                onClick={() => {
                  onCustomerSelect(customer);
                  setIsDropdownOpen(false);
                }}
                className="p-3 cursor-pointer hover:bg-gray-100 transition-colors duration-200 flex items-center"
              >
                <FaUser className="mr-2 text-gray-400" />
                <div>
                  <p className="font-semibold text-gray-800">{customer.name}</p>
                  <p className="text-sm text-gray-600">{customer.phone}</p>
                </div>
              </motion.li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
};

const OrderHistoryTable = ({ orderHistory }) => {
  const router = useRouter();

  const handleViewOrderDetails = (orderId) => {
    window.open(`/OrderShow/${orderId}`, '_blank');
  };  

  return (
    <div className="overflow-x-auto rounded-lg shadow-md">
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            {['Order ID', 'Date', 'Status', 'Items', 'Total Amount', 'Actions'].map((header) => (
              <th key={header} className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                {header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-gray-200">
          {orderHistory.map((order) => (
            <tr key={order.orderId} className="hover:bg-gray-50 transition-colors duration-200">
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{order.orderId}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(order.createdAt).toLocaleDateString()}</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                  order.status === 'Completed' ? 'bg-green-100 text-green-800' :
                  order.status === 'Pending' ? 'bg-yellow-100 text-yellow-800' :
                  'bg-red-100 text-red-800'
                }`}>
                  {order.status}
                </span>
              </td>
              <td className="px-6 py-4 text-sm text-gray-500">
                <ul className="list-disc list-inside">
                  {order.items.map((item, index) => (
                    <li key={index}>
                      {item.itemName.name} - Qty: {item.quantity}
                    </li>
                  ))}
                </ul>
              </td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">${order.totalAmount.toFixed(2)}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => handleViewOrderDetails(order._id)}
                  className="text-indigo-600 hover:text-indigo-900 flex items-center"
                >
                  <FaEye className="mr-2" />
                  View Details
                </motion.button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default function CustomerOrderHistory() {
  const { hasPermission: canViewCustomerReport, loading: loadingPermission } = usePermission('Customer_Report');
  const router = useRouter();
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [orderHistory, setOrderHistory] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchOrderHistory = useCallback(async (customerId) => {
    setLoading(true);
    try {
      const response = await axios.get(`${apiUrl}Reports/api/reports/customer-order-history/${customerId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setOrderHistory(response.data);
    } catch (error) {
      toast.error('Error fetching order history');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (selectedCustomer) {
      fetchOrderHistory(selectedCustomer._id);
    }
  }, [selectedCustomer, fetchOrderHistory]);

  const handleReturn = () => {
    router.back();
  };

  const getItemName = (item) => {
    if (typeof item.itemName === 'string') return item.itemName;
    if (item.itemName && item.itemName.name) return item.itemName.name;
    if (item.name) return item.name;
    return 'Unknown Item';
  };

  const exportToPDF = useCallback(async () => {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4'
    });
  
    const pageWidth = doc.internal.pageSize.width;
    const pageHeight = doc.internal.pageSize.height;
    const margin = 15;
  
    const companyInfo = {
      name: "السلة الانشائية",
      address: "1234 Street Name, City, Country",
      contact: "Phone: 07705127299",
      website: "www.codeklab.com",
      logo: "./image.png"
    };
  
    // Add Arabic font
    doc.addFileToVFS('Amiri-Regular.ttf', arabicFont);
    doc.addFont('Amiri-Regular.ttf', 'Amiri', 'normal');
    doc.setFont('Amiri');
  
    // Colors
    const primaryColor = [41, 128, 185]; // Soft blue
    const secondaryColor = [149, 165, 166]; // Soft gray
    const accentColor = [230, 126, 34]; // Soft orange
  
    // Helper function to draw a line
    const drawLine = (startX, startY, endX, endY, color, width = 0.5) => {
      doc.setDrawColor(...color);
      doc.setLineWidth(width);
      doc.line(startX, startY, endX, endY);
    };
  
    // Header Section
    // Header Section
const addHeader = () => {
  // Background
  doc.setFillColor(...primaryColor);
  doc.rect(0, 0, pageWidth, 40, 'F');

  // Rounded Logo
  const logoSize = 20;
  const logoX = margin;
  const logoY = 10;
  
  // Create a white circular background


  // Add the logo image
  doc.addImage(companyInfo.logo, 'PNG', logoX, logoY, logoSize, logoSize);

  // Create a circular mask
  doc.setDrawColor(...primaryColor);
  doc.setLineWidth(2);
  doc.circle(logoX + logoSize / 2, logoY + logoSize / 2, logoSize / 2, 'S');

  // Company Info
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.text(companyInfo.name, pageWidth - margin, 20, { align: 'right' });

  doc.setFontSize(10);
  doc.text(companyInfo.address, pageWidth - margin, 27, { align: 'right' });
  doc.text(companyInfo.contact, pageWidth - margin, 32, { align: 'right' });
  doc.text(companyInfo.website, pageWidth - margin, 37, { align: 'right' });
};
  
    // Customer Info Section
    const addCustomerInfo = async () => {
      doc.setTextColor(0, 0, 0);
      doc.setFontSize(18);
      doc.text("Customer Statement", pageWidth / 2, 55, { align: 'center' });
  
      drawLine(margin, 60, pageWidth - margin, 60, primaryColor, 0.5);
  
      doc.setFontSize(12);
      doc.text(`Customer: ${selectedCustomer.name}`, margin, 70);
      doc.text(`Phone: ${selectedCustomer.phone}`, margin, 77);
      doc.text(`Statement Date: ${new Date().toLocaleDateString()}`, margin, 84);
  
      // Add QR code
      // const qr = await QRCode.toDataURL(companyInfo.website);
      // doc.addImage(qr, 'PNG', pageWidth - 35, 65, 20, 20);
    };
  
    // Table Data Processing
    const processTableData = () => orderHistory.map(order => [
      `$${order.totalAmount.toFixed(2)}`,
      new Date(order.createdAt).toLocaleDateString('en-us'),
      order.status,
      order.items.map(item => `${getItemName(item)} - الكمية: ${item.quantity}`).join('\n'),
      order.orderId
    ]);
  
    // Adding Table
    const addTable = (tableData) => {
      doc.autoTable({
        head: [['المبلغ الإجمالي', 'التاريخ', 'الحالة', 'العناصر', 'رقم الطلب']],
        body: tableData,
        startY: 95,
        theme: 'plain',
        styles: {
          fontSize: 10,
          cellPadding: 5,
          font: 'Amiri',
          textColor: [0, 0, 0],
          lineColor: [...secondaryColor],
          lineWidth: 0.1
        },
        headStyles: {
          fillColor: [...primaryColor],
          textColor: [255, 255, 255],
          fontStyle: 'bold',
          halign: 'center', // This centers the text in header cells
          valign: 'middle'  // This vertically centers the text
        },
        columnStyles: {
          0: { cellWidth: 30, halign: 'center' },
          1: { cellWidth: 30, halign: 'center' },
          2: { cellWidth: 25, halign: 'center', 
               cellRenderer: (cell, opts) => {
                 const status = cell.raw;
                 let color = [...secondaryColor];
                 if (status === 'Completed') color = [46, 204, 113];
                 if (status === 'Pending') color = [241, 196, 15];
                 if (status === 'Cancelled') color = [231, 76, 60];
                 doc.setFillColor(...color);
                 doc.roundedRect(cell.x + 1, cell.y + 1, cell.width - 2, cell.height - 2, 2, 2, 'F');
                 doc.setTextColor(255, 255, 255);
                 doc.text(status, cell.x + cell.width / 2, cell.y + cell.height / 2, { align: 'center', baseline: 'middle' });
                 return false;
               }
          },
          3: { cellWidth: 'auto', halign: 'right' },
          4: { cellWidth: 25, halign: 'center' }
        },
        alternateRowStyles: {
          fillColor: [245, 245, 245]
        },
        didDrawPage: (data) => {
          addFooter();
        }
      });
    };
  
    // Adding Total Amount
    const addTotalAmount = () => {
      const totalAmount = orderHistory.reduce((sum, order) => sum + order.totalAmount, 0);
      const finalY = doc.autoTable.previous.finalY + 10;
  
      doc.setFillColor(...accentColor);
      doc.roundedRect(pageWidth - 80, finalY, 65, 25, 3, 3, 'F');
  
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(12);
      doc.text('Total Amount Due:', pageWidth - 75, finalY + 10);
      doc.setFontSize(16);
      doc.text(`$${totalAmount.toFixed(2)}`, pageWidth - 15, finalY + 20, { align: 'right' });
    };
  
    // Footer
    const addFooter = () => {
      const pageCount = doc.internal.getNumberOfPages();
      doc.setFontSize(10);
      doc.setTextColor(...secondaryColor);
      doc.text(`Page ${doc.internal.getCurrentPageInfo().pageNumber} of ${pageCount}`, pageWidth - margin, pageHeight - 10, { align: 'right' });
      doc.text('شكراً لتسوقك منا', margin, pageHeight - 10);
  
      drawLine(margin, pageHeight - 15, pageWidth - margin, pageHeight - 15, secondaryColor, 0.5);
    };
  
    // Generate PDF
    await addHeader();
    await addCustomerInfo();
    const tableData = processTableData();
    addTable(tableData);
    addTotalAmount();
  
    // Save PDF
    doc.save(`customer_statement_${selectedCustomer.name}.pdf`);
  }, [orderHistory, selectedCustomer, getItemName]);


  const exportToExcel = useCallback(() => {
    const wsData = orderHistory.flatMap(order => 
      order.items.map((item, index) => ({
        'Order ID': index === 0 ? order.orderId : '',
        'Date': index === 0 ? new Date(order.createdAt).toLocaleDateString() : '',
        'Status': index === 0 ? order.status : '',
        'Item': getItemName(item),
        'Quantity': item.quantity,
        'Total Amount': index === 0 ? `$${order.totalAmount.toFixed(2)}` : ''
      }))
    );

    const ws = XLSX.utils.json_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Order History");
    XLSX.writeFile(wb, `order_history_${selectedCustomer.name}.xlsx`);
  }, [orderHistory, selectedCustomer]);

  if (loadingPermission) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100">
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
        >
          <FaSpinner className="text-4xl text-blue-500" />
        </motion.div>
      </div>
    );
  }

  if (!canViewCustomerReport) {
    return <NotAuth />;
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
      className="min-h-screen p-8 bg-gray-100"
    >
      <ToastContainer position="top-right" autoClose={3000} />
      <div className="max-w-7xl mx-auto">
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-gray-800">Customer Order History</h1>
          <CustomAwesomeButton
 buttonType="electric"
 onPress={handleReturn}
 isRTL={true}
>
<div className="flex flex-row">
<FaArrowLeft className="mr-2 mt-1" />
          رجوع
</div>
</CustomAwesomeButton>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-md mb-8">
          <h2 className="text-xl font-semibold mb-4 text-gray-800">Search Customer</h2>
          <CustomerSearch onCustomerSelect={setSelectedCustomer} />
        </div>

        {selectedCustomer && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="bg-white p-6 rounded-lg shadow-md mb-8"
          >
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-semibold text-gray-800">Order History for {selectedCustomer.name}</h2>
              <div className="flex space-x-4">
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={exportToPDF}
                  className="flex items-center px-4 py-2 text-white bg-red-500 rounded-md hover:bg-red-600 transition duration-300 shadow-sm"
                  disabled={loading || orderHistory.length === 0}
                >
                  <FaFilePdf className="mr-2" />
                  Export to PDF
                </motion.button>
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={exportToExcel}
                  className="flex items-center px-4 py-2 text-white bg-green-500 rounded-md hover:bg-green-600 transition duration-300 shadow-sm"
                  disabled={loading ||orderHistory.length === 0}
                  >
                    <FaFileExcel className="mr-2" />
                    Export to Excel
                  </motion.button>
                </div>
              </div>
  
              <AnimatePresence>
                {loading && (
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="flex justify-center items-center h-32"
                  >
                    <FaSpinner className="animate-spin text-4xl text-blue-500" />
                  </motion.div>
                )}
              </AnimatePresence>
  
              {!loading && orderHistory.length > 0 && (
                <OrderHistoryTable orderHistory={orderHistory} />
              )}
  
              {!loading && orderHistory.length === 0 && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.5 }}
                  className="bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded-md"
                  role="alert"
                >
                  <p className="font-semibold text-yellow-800">No Orders Found</p>
                  <p className="text-yellow-700">This customer has no order history at the moment.</p>
                </motion.div>
              )}
            </motion.div>
          )}
        </div>
      </motion.div>
    );
  }